"""heatup.workflow
===================
Targets vs references - the screening funnel for *many* candidate structures.

(For ONE phase with a typed verdict - the entry point other software should call - see
:func:`heatup.screen` in :mod:`heatup.api`.)

* **references**  known phases (database / candidates / Materials Project) that span the
  hull.  They are never judged.
* **targets**     structures under test (your own, or generated by
  :mod:`heatup.generation`).

Funnel (cheapest first, every step cached)::

    relax all targets
      -> 0 K pre-screen   E_hull(0 K) vs relaxed references  (drop > generation.prescreen_e_hull_eV)
      -> run_pipeline()   Gates 1 -> 0 -> 2 -> 3 for the survivors

``screen_many`` returns one row per target (also written to ``<out>/screening.json`` and ``.csv``),
sorted best first.
"""

from __future__ import annotations

import csv
import logging
import os


from heatup.config import forced, STATUS_FAIL, STATUS_MISSING, STATUS_OK, STATUS_WARN, cfg
from heatup.paths import PhaseDir, write_json
from heatup.phases import Phase, _mp_query, find_reference_phases, phase_from_dir
from heatup.runtime import run_step

log = logging.getLogger("heatup")

_RANK = {STATUS_OK: 0, STATUS_WARN: 1, STATUS_MISSING: 2, STATUS_FAIL: 3, "pruned": 4, "error": 5}


def prescreen(targets: list[Phase], references: list[Phase], device: str | None = None,
              force: bool | None = None) -> dict[str, dict]:
    """Relax references + targets, return ``{target.tag: {"e_hull_0K": ..., "relaxed": bool}}``."""
    from heatup.thermodynamic import hull_distance
    from heatup.free_energy import reference_energy

    def relaxed(ps):
        ok = []
        for p in ps:
            if p.phase_dir.has_relaxation() and not forced("relax", force):
                ok.append(p)
            elif run_step("relax", p.phase_dir, device=device, force=force):
                ok.append(p)
            else:
                log.warning("%s: relaxation failed", p.tag)
        return ok

    refs = relaxed(references)
    ref_h = {}
    for p in refs:
        h = reference_energy(p.phase_dir)
        if h is not None:
            ref_h[p.tag] = (p.composition, h)
    res: dict[str, dict] = {}
    for t in relaxed(targets):
        h = reference_energy(t.phase_dir)
        try:
            e = hull_distance(t.composition, h, {k: v for k, v in ref_h.items() if k != t.tag})["e_hull_eV"]
        except Exception as exc:  # noqa: BLE001
            res[t.tag] = {"e_hull_0K": None, "error": str(exc)}
            continue
        res[t.tag] = {"e_hull_0K": float(e)}
    return res


def screen_many(targets: "list[str | PhaseDir]", out_dir: str | None = None, device: str | None = None,
           operating_T: float | None = None, md_temperatures: list[float] | None = None,
           prescreen_only: bool = False, force: bool | None = None,
           **pipeline_kw) -> list[dict]:
    from heatup.pipeline import run_pipeline

    tph = [p for p in (phase_from_dir(t, "target") for t in targets) if p]
    if not tph:
        raise ValueError("no readable target structures")
    elements = frozenset().union(*(p.elements for p in tph))
    mp_docs = _mp_query(elements) if "mp-api" in cfg.phases.sources else None
    refs = find_reference_phases(elements, mp_docs, exclude=[t.phase_dir for t in tph])
    log.info("screening %d target(s) against %d reference phase(s)", len(tph), len(refs))
    pre = prescreen(tph, refs, device, force)

    rows: list[dict] = []
    for t in tph:
        row = {"tag": t.tag, "formula": t.formula, "source": t.source,
               "e_hull_0K_eV": pre.get(t.tag, {}).get("e_hull_0K"), "overall": "error",
               "gates": {}, "message": pre.get(t.tag, {}).get("error", "")}
        e0 = row["e_hull_0K_eV"]
        if e0 is None:
            row["message"] = row["message"] or "relaxation failed"
        elif e0 > cfg.generation.prescreen_e_hull_eV:
            row["overall"] = "pruned"
            row["message"] = f"0 K hull distance {1e3 * e0:.0f} meV/atom > {1e3 * cfg.generation.prescreen_e_hull_eV:.0f}"
        elif not prescreen_only:
            rep = run_pipeline(t.phase_dir, operating_T=operating_T, device=device,
                               md_temperatures=md_temperatures, force=force,
                               mp_docs=mp_docs, **pipeline_kw)
            row["overall"] = rep["overall"]
            row["gates"] = {g: (rep[g] or {}).get("status") for g in
                            ("mechanical", "structural_transition", "vibrational", "thermodynamic")}
            th = rep.get("thermodynamic") or {}
            row["e_hull_T_eV"] = th.get("e_hull_at_T_eV")
            row["message"] = "; ".join(f for f in rep["flags"] if f.startswith("[FAIL]"))[:300]
        else:
            row["overall"] = STATUS_MISSING
            row["message"] = "passed 0 K pre-screen"
        rows.append(row)
    rows.sort(key=lambda r: (_RANK.get(r["overall"], 9),
                             r.get("e_hull_T_eV") if r.get("e_hull_T_eV") is not None else 9,
                             r["e_hull_0K_eV"] if r["e_hull_0K_eV"] is not None else 9))
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
        write_json(os.path.join(out_dir, "screening.json"), rows)
        cols = ["tag", "formula", "source", "overall", "e_hull_0K_eV", "e_hull_T_eV", "message"]
        with open(os.path.join(out_dir, "screening.csv"), "w", newline="") as fh:
            w = csv.DictWriter(fh, fieldnames=cols, extrasaction="ignore")
            w.writeheader()
            w.writerows(rows)
    return rows


def generate_and_screen(composition: dict, n: int | None = None, method: str | None = None,
                        out_dir: str | None = None, **kw) -> list[dict]:
    """Generate *n* candidates for the integer *composition* (e.g. ``{"Ba":1,"Ti":1,"O":3}``) and screen them."""
    from heatup.generation import generate
    phases = generate(composition, n=n, method=method)
    return screen_many([p.phase_dir for p in phases], out_dir=out_dir, **kw)
